	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void capturedResourceDatasetRoundTripPreservesExplicitReadAndOwnedSelectors(boolean empty) {
		RemoteBNode remote = remoteNode();
		SimpleDataset original = empty ? new SimpleDataset() : dataset(remote, remote);
		original.setExplicitReadDataset(true);
		original.addDefaultRemoveGraph(null);
		original.setDefaultInsertGraph(remote);
		var identity = LmdbPipelinePlanCache.DatasetIdentity.of(original);
		var restored = identity.toDataset();
		assertTrue(restored.isExplicitReadDataset());
		assertEquals(identity, LmdbPipelinePlanCache.DatasetIdentity.of(restored));
		assertEquals(original.getDefaultGraphResources(), restored.getDefaultGraphResources());
		assertEquals(original.getNamedGraphResources(), restored.getNamedGraphResources());
		original.addDefaultGraph(VF.createIRI("urn:after-capture"));
		assertEquals(empty ? 0 : 1, identity.defaultGraphs().size(), "captured selectors own their immutable set");
		assertEquals(identity, LmdbPipelinePlanCache.DatasetIdentity.of(restored));
	}

	@Test
	void canonicalSelectorKeysPreserveRawEntryCountAndIgnoreSetOrder() {
		Object origin = new Object();
		RemoteBNode first = remoteNode(new BlankNodeAllocationScope("entry-a-", id -> false), origin, true);
		RemoteBNode second = remoteNode(new BlankNodeAllocationScope("entry-b-", id -> false), origin, true);
		assertNotEquals(first.getID(), second.getID());
		assertTrue(RemoteBNode.sameTrustedIdentity(first, second));
		SimpleDataset one = dataset(null, first);
		SimpleDataset two = dataset(null, first);
		two.addNamedGraph(second);
		SimpleDataset reversed = dataset(null, second);
		reversed.addNamedGraph(first);
		assertEquals(1, one.getNamedGraphResources().size());
		assertEquals(2, two.getNamedGraphResources().size());
		assertEquals(2, reversed.getNamedGraphResources().size());
		assertNotEquals(LmdbPipelinePlanCache.DatasetIdentity.of(one), LmdbPipelinePlanCache.DatasetIdentity.of(two),
				"private semantic identity must not collapse extra raw selector entries");
		assertEquals(LmdbPipelinePlanCache.DatasetIdentity.of(two), LmdbPipelinePlanCache.DatasetIdentity.of(reversed));
		assertEquals(LmdbPipelinePlanCache.DatasetIdentity.of(two).hashCode(),
				LmdbPipelinePlanCache.DatasetIdentity.of(reversed).hashCode());
	}

	@Test
	void actualGraphOverSuppliedTrustedAliasesKeepsTheOrdinaryOracleBag(@TempDir Path directory) {
		Object origin = new Object();
		RemoteBNode first = remoteNode(new BlankNodeAllocationScope("graph-a-", id -> false), origin, true);
		RemoteBNode second = remoteNode(new BlankNodeAllocationScope("graph-b-", id -> false), origin, true);
		assertNotEquals(first.getID(), second.getID());
		assertTrue(RemoteBNode.sameTrustedIdentity(first, second));
		SimpleDataset one = dataset(null, first);
		SimpleDataset two = dataset(null, first);
		two.addNamedGraph(second);
		SimpleDataset reversed = dataset(null, second);
		reversed.addNamedGraph(first);
		SailRepository nativeRepository = new SailRepository(new LmdbStore(directory.toFile()));
		SailRepository oracle = new SailRepository(new MemoryStore());
		nativeRepository.init();
		oracle.init();
		try (var nativeConnection = nativeRepository.getConnection(); var memoryConnection = oracle.getConnection()) {
			// These are two independently stored local contexts. The private origin premise above is used only to
			// exercise the cache-key boundary; no duplicate-remote-graph cardinality is assumed.
			for (var connection : List.of(nativeConnection, memoryConnection)) {
				connection.add(VF.createIRI("urn:selector:first"), P, VF.createLiteral("first"),
						VF.createBNode(first.getID()));
				connection.add(VF.createIRI("urn:selector:second"), P, VF.createLiteral("second"),
						VF.createBNode(second.getID()));
			}
			String text = "SELECT ?g ?o WHERE { GRAPH ?g { ?s <urn:dataset:p> ?o } }";
			TupleQuery nativeQuery = nativeConnection.prepareTupleQuery(text);
			TupleQuery oracleQuery = memoryConnection.prepareTupleQuery(text);
			for (SimpleDataset selectors : List.of(two, reversed, one, two)) {
				nativeQuery.setDataset(selectors);
				oracleQuery.setDataset(selectors);
				Map<BindingSet, Integer> expected = graphBag(oracleQuery);
				assertFalse(expected.isEmpty(), "the actual oracle must reach the selected GRAPH body");
				Map<BindingSet, Integer> actual = graphBag(nativeQuery);
				System.out.println("trusted-selector-actual rawEntries=" + selectors.getNamedGraphResources().size()
						+ " oracle=" + expected + " native=" + actual);
				assertEquals(expected, actual);
			}
			Explanation explanation = nativeQuery.explain(Explanation.Level.Executed);
			var pattern = LmdbDistinctCursorSkipTestSupport.firstStatementPattern((TupleExpr) explanation.tupleExpr());
			assertTrue(pattern.getSourceRowsMatchedActual() > 0, explanation::toString);
		} finally {
			try {
				nativeRepository.shutDown();
			} finally {
				oracle.shutDown();
			}
		}
	}

