	@Test
	void ordinarySerializationDoesNotRestoreRemoteCacheAuthority() throws Exception {
		RemoteBNode original = remoteNode();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(original);
		}
		RemoteBNode restored;
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = (RemoteBNode) input.readObject();
		}
		assertEquals(original.getID(), restored.getID());
		assertNull(restored.getProvenance());
		assertNotEquals(bindingIdentity(original), bindingIdentity(restored));
		assertNotEquals(bindingIdentity(VF.createBNode(restored.getID())), bindingIdentity(restored));
		assertEquals(bindingIdentity(restored), bindingIdentity(restored));
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, 256 })
	void nestedTripleIdentityKeepsRemoteAuthorityAtEveryDepth(int depth) {
		RemoteBNode remote = remoteNode();
		Value trusted = remote;
		Value forged = VF.createBNode(remote.getID());
		Value copied = RemoteBNode.preserveProvenance(remote, forged);
		for (int index = 0; index < depth; index++) {
			trusted = VF.createTripleTerm(VF.createIRI("urn:nested:s"), P, trusted);
			forged = VF.createTripleTerm(VF.createIRI("urn:nested:s"), P, forged);
			copied = VF.createTripleTerm(VF.createIRI("urn:nested:s"), P, copied);
		}
		assertNotEquals(bindingIdentity(trusted), bindingIdentity(forged));
		assertEquals(bindingIdentity(trusted), bindingIdentity(copied));
		assertEquals(bindingIdentity(trusted).hashCode(), bindingIdentity(copied).hashCode());
	}

	@Test
	void repeatedKeyHashesDoNotRevisitSharedTripleTerms() {
		AtomicInteger visits = new AtomicInteger();
		Value shared = VF.createLiteral("leaf");
		int depth = 64;
		for (int index = 0; index < depth; index++) {
			shared = new CountingTripleTerm(VF.createIRI("urn:shared:s"), P, shared, visits);
		}
		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("first", shared);
		bindings.addBinding("second", shared);
		var identity = LmdbPipelinePlanCache.BindingIdentity.of(bindings);
		int expected = identity.hashCode();
		for (int index = 0; index < 50; index++) {
			assertEquals(expected, identity.hashCode());
		}
		assertTrue(visits.get() <= 12 * depth + 20,
				"capture may traverse each shared term; repeated cache hashes must use captured immutable hashes: "
						+ visits.get());
	}

